using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RegionalTradeTests
{
    internal static WorldSession Start(string person="person:nobunaga")=>new(NewGameWorld.Create(NewGameWorld.Scenario(),[],person,42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:RegionalTrade.Policy));
    static RegionalTradeState State(WorldSession s)=>s.DiagnosticSnapshot().Trade!;
    static CommandResult Act(WorldSession s,TradeAction a,EntityId? contract=null,string site="site:castle",long amount=0,string? dest=null,string? id=null)=>s.TradeRice(new(new(id??"request:trade/"+s.Revision),a,new(site),contract,dest==null?null:new(dest),amount),s.PlayerControl,s.Revision);
    static EntityId Quote(WorldSession s,string site="site:castle",string dest="site:kofu",long amount=100){var r=Act(s,TradeAction.Quote,site:site,amount:amount,dest:dest);Assert.Equal(ResultCode.Accepted,r.Code);return State(s).Deals.Last().Id;}
    static EntityId Carry(WorldSession s){var id=Quote(s);Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.Accept,id).Code);var collect=Act(s,TradeAction.Collect,id);Assert.True(collect.Code==ResultCode.Accepted,collect.VisibleReason);return id;}
    static void Advance(WorldSession s,long at){while(s.Seconds<at){long old=s.Seconds;s.SetPaused(false);s.AdvanceTo(at,100000);Assert.True(s.Seconds>old);}}
    static void Go(WorldSession s,string dest){Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:trip/"+s.Revision,dest),s.Revision).Code);Advance(s,s.Seconds+1);Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs[^1].EndAt);}
    [Fact]public void QuoteDoesNotSpendAcceptProtectsThenCollectMovesActualRiceAndCoins(){var s=Start();var id=Quote(s);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.Accept,id).Code);Assert.Equal(800,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(1000,s.DiagnosticSnapshot().ResourceLots.Single(l=>l.Id==NewGameWork.Wallet(s.PlayerControl)).Quantity);Assert.Equal(1900,s.RegionalTradeView()!.RiceAvailable);Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.Collect,id).Code);Assert.Equal(800,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(1900,State(s).Markets[0].Rice);Assert.Equal(4200,State(s).Markets[0].Cash);Assert.Equal(TradePhase.Carrying,State(s).Deals.Single().Phase);}
    [Theory][InlineData(0)][InlineData(-1)][InlineData(101)]public void InvalidQuantityIsAtomic(long amount){var s=Start();var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,TradeAction.Quote,amount:amount,dest:"site:kofu").Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void PhysicalRouteArrivalDeliveryDebtAndSettlementAreSeparate(){var s=Start();var id=Carry(s);Assert.Equal(ResultCode.NotAvailable,Act(s,TradeAction.OfferSale,id,"site:kofu").Code);Go(s,"kofu");Assert.Equal("site:kofu",s.RegionalTradeView()!.Site.Value);Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.OfferSale,id,"site:kofu").Code);long value=State(s).Deals.Single().SalePrice*100;Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.Deliver,id,"site:kofu").Code);Assert.Equal(800,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(2100,State(s).Markets.Single(m=>m.Site.Value=="site:kofu").Rice);Assert.Equal(TradePhase.Delivered,State(s).Deals.Single().Phase);Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.Settle,id,"site:kofu").Code);Assert.Equal(800+value,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(TradePhase.Settled,State(s).Deals.Single().Phase);}
    [Fact]public void AcceptedCancellationOrExpiryReleasesBothReservations(){foreach(bool expire in new[]{false,true}){var s=Start();var id=Quote(s);Act(s,TradeAction.Accept,id);if(expire)Advance(s,7*86400+1);else Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.Cancel,id).Code);Assert.Equal(1000,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(2000,s.RegionalTradeView()!.RiceAvailable);Assert.Equal(ResultCode.NotAvailable,Act(s,TradeAction.Collect,id).Code);}}
    [Fact]public void CarriedCancellationPreservesGoodsAndAllowsLocalResaleAtCurrentPrice(){var s=Start();var id=Carry(s);Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.Cancel,id).Code);Assert.Equal(TradePhase.ReturnRequired,State(s).Deals.Single().Phase);Assert.Equal(1900,State(s).Markets[0].Rice);Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.OfferSale,id).Code);Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.Deliver,id).Code);Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.Settle,id).Code);Assert.Equal(2000,State(s).Markets[0].Rice);Assert.Equal(900,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));}
    [Fact]public void ExplicitHouseSupplyMovesPrivateRiceWithoutChangingMilitaryOrPrivateCoins(){var s=Start();var id=Carry(s);var before=s.DiagnosticSnapshot();Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.SupplyHouse,id).Code);Assert.Equal(3100,s.CommunityEconomyView()!.Accounts.HouseRice);Assert.Equal(800,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(ContractJson.Write(before.Units),ContractJson.Write(s.DiagnosticSnapshot().Units));Assert.Equal(TradePhase.Supplied,State(s).Deals.Single().Phase);Assert.Equal(ResultCode.NotAvailable,Act(s,TradeAction.SupplyHouse,id).Code);}
    [Fact]public void WrongActorRemoteSiteAndDuplicateOriginalCannotSpend(){var s=Start();var id=Quote(s);var i=new TradeInput(new("request:stable"),TradeAction.Accept,new("site:castle"),id);Assert.Equal(ResultCode.NotAvailable,s.TradeRice(i,new("person:shingen"),s.Revision).Code);Assert.Equal(ResultCode.StateChanged,s.TradeRice(i,s.PlayerControl,s.Revision+10).Code);Assert.Equal(ResultCode.Accepted,s.TradeRice(i,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.AlreadyAccepted,s.TradeRice(i,s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.TradeRice(i with{Action=TradeAction.Collect},s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:stable","kofu"),s.Revision).Code);}
    [Fact]public void MarketAndPriceTamperingCannotLoad(){var s=Start();Quote(s);var w=s.DiagnosticSnapshot();w.Trade=w.Trade! with{Markets=[..w.Trade.Markets.Select(m=>m with{Rice=999})]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));w=s.DiagnosticSnapshot();w.Trade=w.Trade! with{Entries=[w.Trade.Entries.Single() with{Price=1}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void PreviousV2WorldKeepsBytesAndRejectsTradeStateInjection(){var old=new WorldSession(NewGameWorld.Create(NewGameWorld.Scenario(),[],"person:nobunaga",economyPolicy:CommunityEconomy.Policy));var bytes=ContractJson.Write(old.DiagnosticSnapshot());Assert.DoesNotContain("Trade",System.Text.Encoding.UTF8.GetString(bytes));Assert.Equal(bytes,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(bytes)).DiagnosticSnapshot()));var w=old.DiagnosticSnapshot();w.Trade=Start().DiagnosticSnapshot().Trade;Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}

    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)]
    public void ActualGenerationRecoveryAtEachPhysicalStageHasIdenticalFuture(int phase)
    {
        var a=Start();var id=Quote(a);Act(a,TradeAction.Accept,id);if(phase>0)Act(a,TradeAction.Collect,id);
        if(phase==1){a.Submit(TravelWorld.Move(a.DiagnosticSnapshot(),"request:save-trip","kofu"),a.Revision);Advance(a,a.Seconds+11);Assert.Null(a.RegionalTradeView());}
        if(phase is 2 or 3){Go(a,"kofu");Act(a,TradeAction.OfferSale,id,"site:kofu");Act(a,TradeAction.Deliver,id,"site:kofu");if(phase==3)Act(a,TradeAction.Settle,id,"site:kofu");}
        if(phase==4)Act(a,TradeAction.SupplyHouse,id);
        a.SetPaused(true);var w=a.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"regional-trade-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(a,"trade",w.WorldId).Published);var host=new WorldSessionHost(Start());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("trade"),host.Current,host.Current.Revision));var b=host.Current;
        Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.RegionalTradeView()),ContractJson.Write(b.RegionalTradeView()));Export(a,b,new[]{"trade-accepted","trade-travel","trade-delivered","trade-settled","trade-supplied"}[phase]);
        foreach(var s in new[]{a,b}){if(phase==0)Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.Collect,id).Code);if(phase==1){Advance(s,s.DiagnosticSnapshot().Branches!.Journeys.Last().Legs[^1].EndAt);Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.OfferSale,id,"site:kofu").Code);Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.Deliver,id,"site:kofu").Code);}if(phase is 1 or 2)Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.Settle,id,"site:kofu").Code);Advance(s,s.Seconds+86400);}
        Assert.Equal(ContractJson.Write(a.DiagnosticSnapshot()),ContractJson.Write(b.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(a.CommunityEconomyView()),ContractJson.Write(b.CommunityEconomyView()));
    }
    [Fact]public void ExistingCompanionPaymentCannotConsumeTradeReservationThenExpiryRestoresFreedom()
    {
        var player=NewGameWorldTests.Officer(role:StartTemplate.Ronin,site:"site:castle");var friend=player with{Id="created:trade-friend"};var setup=NewGameSetup.Preview(NewGameWorld.Scenario(),new([player,friend],[]));Assert.True(setup.IsEligible());var s=new WorldSession(NewGameWorld.Create(setup.World!,[player,friend],player.Id,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:RegionalTrade.Policy,companionPolicy:PersonalCompanions.Policy));
        for(int n=0;n<8;n++){var id=Carry(s);Act(s,TradeAction.OfferSale,id);Act(s,TradeAction.Deliver,id);Act(s,TradeAction.Settle,id);}Assert.Equal(200,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));var pending=Quote(s);Act(s,TradeAction.Accept,pending);Assert.Equal(0,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));var i=new CompanionInput(new("request:trade-reserved-pay"),new(friend.Id),CompanionAction.Agree,20);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageCompanion(i,s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Advance(s,7*86400+1);Assert.Equal(200,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(ResultCode.Accepted,s.ManageCompanion(i,s.PlayerControl,s.Revision).Code);
    }
    [Fact]public void LocalDemandChangesNewQuoteButDoesNotRewriteOlderContractPrice(){var s=Start();for(int n=0;n<3;n++){var id=Carry(s);Act(s,TradeAction.SupplyHouse,id);}Assert.Equal(3300,s.CommunityEconomyView()!.Accounts.HouseRice);var q=Quote(s);Assert.Equal(3,State(s).Deals.Single(d=>d.Id==q).PurchasePrice);Assert.All(State(s).Deals.Take(3),d=>Assert.Equal(2,d.PurchasePrice));}
    [Fact]public void NoFreshRemoteMarketOrInstantDeliveryWhileOnRoad(){var s=Start();var id=Carry(s);s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:travel-hidden","kofu"),s.Revision);Advance(s,s.Seconds+11);Assert.Null(s.RegionalTradeView());var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,TradeAction.OfferSale,id,"site:kofu").Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));Assert.Equal(2000,State(s).Markets.Single(m=>m.Site.Value=="site:kofu").Rice);Assert.Equal(TradePhase.Carrying,State(s).Deals.Single().Phase);}
    [Fact]public void ForeignHouseCannotReceivePrivateCargoWithoutDispositionAuthority(){var s=Start();var id=Carry(s);Go(s,"kofu");var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,Act(s,TradeAction.SupplyHouse,id,"site:kofu").Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void DeliveredDebtProtectsMerchantCashAndSurvivesTimeAndCannotBeCancelled(){var s=Start();var id=Carry(s);Act(s,TradeAction.OfferSale,id);Act(s,TradeAction.Deliver,id);Assert.Equal(4100,s.RegionalTradeView()!.CashAvailable);Advance(s,20*86400);Assert.Equal(TradePhase.Delivered,State(s).Deals.Single().Phase);Assert.Equal(ResultCode.NotAvailable,Act(s,TradeAction.Cancel,id).Code);Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.Settle,id).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,TradeAction.Settle,id).Code);}
    [Fact]public void PurchasePriceAndStockStayReservedWithinWindowButSaleQuoteMustBeRefreshed(){var s=Start();var id=Quote(s);Act(s,TradeAction.Accept,id);Advance(s,7*86400);Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.Collect,id).Code);Act(s,TradeAction.OfferSale,id);Advance(s,s.Seconds+86401);Assert.Equal(TradePhase.Carrying,State(s).Deals.Single().Phase);Assert.Equal(ResultCode.NotAvailable,Act(s,TradeAction.Deliver,id).Code);Assert.Equal(ResultCode.Accepted,Act(s,TradeAction.OfferSale,id).Code);}
    [Fact]public void NormalEntryProfilePersistsNewPolicyAndBuildsMarketAndCommunityWithoutOldSaveMigration(){var store=new NewCampaignStore(Path.Combine(Path.GetTempPath(),"trade-profile-"+Guid.NewGuid().ToString("N")));var p=store.New(NewGameWorld.Scenario(HistoricalStartCatalog.Current),[],"person:nobunaga",42,NewGameWorld.CompactPersonalAuthority,HistoricalStartCatalog.Current,NewGameNpcRoutine.Policy,LocalInspectionFindings.Policy,WorkFollowup.Policy,null,VoyageExpense.Standard,NpcArmies.CompactCombatPolicy,RegionalTrade.Policy,PersonalCompanions.RetainerReleasePolicy,TruceNegotiations.Policy,PrivateInformation.Policy,PrivateStanddown.Policy);Assert.Equal(RegionalTrade.Policy,store.Read(p.Instance).EconomyPolicy);var s=new WorldSession(NewCampaignStore.Build(p));Assert.NotNull(s.RegionalTradeView());Assert.NotNull(s.CommunityEconomyView());}
    [Fact]public void SuppliesAreActualHouseRiceAvailableForLaterWorkAndRelief(){var s=Start();var id=Carry(s);Act(s,TradeAction.SupplyHouse,id);Assert.Equal(ResultCode.Accepted,s.ManageCommunity(new(new("request:import-relief"),new("site:castle"),EconomyAction.RelieveVillage,3100),s.PlayerControl,s.Revision).Code);Assert.Equal(0,s.CommunityEconomyView()!.Accounts.HouseRice);Assert.Equal(13100,s.CommunityEconomyView()!.Accounts.VillageRice);Assert.Equal(800,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));}
    static void Export(WorldSession a,WorldSession b,string name){var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(string.IsNullOrEmpty(dir))return;Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,name+".before.json"),ContractJson.Write(a.DiagnosticSnapshot()));File.WriteAllBytes(Path.Combine(dir,name+".restored.json"),ContractJson.Write(b.DiagnosticSnapshot()));}
    [Fact]public void UnknownClosureDoesNotChangeQuoteOrPlannedJourneyAndDoesNotTeleportCargo(){var original=Start();var w=original.DiagnosticSnapshot();var expected=TravelWorld.Move(w,"request:closed-trip","kofu");string edge=BranchRoutes.Plan("castle","kofu",[],w:w,departureAt:1)[0];w.Couriers=w.Couriers! with{Conditions=[..w.Couriers.Conditions,new(1,edge,true)]};var s=new WorldSession(w);var id=Carry(s);Assert.Equal(expected.WorkSeconds,TravelWorld.Move(s.DiagnosticSnapshot(),"request:closed-trip","kofu").WorkSeconds);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:closed-trip","kofu"),s.Revision).Code);Advance(s,2);Assert.Equal(TradePhase.Carrying,State(s).Deals.Single().Phase);Assert.Equal(2000,State(s).Markets.Single(m=>m.Site.Value=="site:kofu").Rice);Assert.Equal(ResultCode.NotAvailable,Act(s,TradeAction.Deliver,id,"site:kofu").Code);}
}
